'use strict';
/* NovaData V3: one linear narrative, no external dependency or Gemini account. */
const STORAGE='novadata-narrativa-v3';
const OPTIONS={A:'Supervisión humana mínima',B:'Modelo híbrido con validación humana',C:'IA como insumo estratégico'};
const CHAPTERS=[
 {title:'La dirección quiere confiar en la IA',subtitle:'La junta recibe los primeros resultados del nuevo sistema.',story:'NovaData Consulting es una firma mexicana de análisis de mercados para bancos, fintechs y fondos de inversión. Su modelo híbrido de IA redujo un 30 % el tiempo de elaboración de reportes. La dirección quiere aprovechar esa eficiencia para delegar más decisiones al sistema. Ahora el modelo anticipa una contracción fintech y recomienda suspender inversiones en innovación.',task:'Con la información disponible, ¿qué autonomía otorgarías al modelo?',evidence:[['Beneficio demostrado','Los reportes tardan un 30 % menos en elaborarse.'],['Consistencia','El equipo observa mayor coherencia entre las proyecciones.'],['Entradas del modelo','Utiliza indicadores bursátiles, redes sociales y reportes económicos.'],['Propuesta algorítmica','El modelo recomienda suspender inversiones en innovación por una contracción prevista.']],zoom:'Comparte A, B o C y el dato que más influyó en tu primera decisión.'},
 {title:'Los analistas discrepan',subtitle:'Llega un informe que contradice la recomendación del algoritmo.',story:'Antes de que la junta apruebe la suspensión de inversiones, los analistas presentan indicios de recuperación del mercado fintech. También señalan que el modelo no explica con claridad algunas correlaciones. La discusión cambia: ya no basta saber cuánto tiempo ahorra la herramienta, hay que evaluar qué información está dejando fuera.',task:'¿Mantienes tu alternativa anterior o la modificas? Fundamenta el cambio —o la continuidad— con un dato concreto.',evidence:[['Observación del equipo','Los analistas identifican señales de recuperación.'],['Interpretabilidad','Algunas recomendaciones carecen de explicaciones suficientes.'],['Contexto incompleto','Las relaciones con socios y los efectos reputacionales están poco representados.'],['Sesgo potencial','Los consultores cuestionan la pérdida del juicio profesional.']],zoom:'¿Quién cambió su decisión? Explica qué evidencia lo hizo cambiar.'},
 {title:'La decisión tiene consecuencias',subtitle:'El costo de equivocarse va más allá de la precisión.',story:'La junta debe considerar que suspender inversiones podría frenar oportunidades futuras, mientras ignorar una contracción podría exponer recursos. Además, la automatización afecta a colaboradores, clientes y socios estratégicos. Una buena recomendación tiene que identificar quién asume la responsabilidad si la decisión falla.',task:'Elige el riesgo que pondrías primero en la agenda y justifica por qué.',evidence:[['Financiero','Una decisión errónea puede afectar inversiones y recursos.'],['Estratégico','La empresa podría perder competitividad u oportunidades.'],['Organizacional','La automatización puede provocar reestructuración y resistencia laboral.'],['Ético y reputacional','Clientes y socios pueden cuestionar decisiones opacas.']],zoom:'Escucha un compañero con un riesgo prioritario distinto al tuyo.'},
 {title:'El consejo se divide',subtitle:'Dos visiones de gobernanza compiten por la decisión.',story:'El comité de innovación propone que las decisiones importantes sean revisadas por un consejo humano. El consejo de administración teme perder velocidad y eficiencia. Como integrante de la junta, debes proponer una forma de supervisión que sea verificable, sin convertir la revisión en un trámite superficial.',task:'Propón al menos dos salvaguardas concretas y defendibles.',evidence:[['Comité de innovación','Solicita revisión humana de decisiones críticas y consecuencias éticas.'],['Consejo de administración','Advierte que los controles podrían disminuir la rapidez.'],['Responsabilidad','Se necesita establecer quién aprueba, documenta y supervisa.']],zoom:'¿Qué salvaguarda aceptarían tanto la dirección como el comité técnico?'},
 {title:'La junta exige un veredicto',subtitle:'Es momento de defender una política de autonomía.',story:'Después de revisar la eficiencia, las contradicciones, los riesgos y las propuestas de gobernanza, la junta debe fijar una política para el próximo ciclo de planeación. Elige A, B o C una última vez. No basta con señalar la alternativa: debes precisar qué evidencia la respalda y bajo qué condición aceptarías elevar la autonomía.',task:'Emite una postura final y formula una condición que podría comprobarse.',evidence:[['Eficiencia','La reducción del 30 % en tiempo está documentada en el caso.'],['Limitación','La recomendación de suspender innovación tiene explicabilidad insuficiente.'],['Conflicto','El equipo humano identifica señales alternativas sobre fintech.'],['Gobernanza','La responsabilidad de la decisión permanece en la organización.']],zoom:'Defiende tu veredicto frente a una persona que haya elegido otra alternativa.'}
];
const CRITIQUE={A:'¿Quién detectaría y respondería por una suspensión equivocada de inversiones bajo supervisión mínima?',B:'¿Qué haría que la validación humana aportara evidencia en vez de convertirse en una firma automática?',C:'¿Cómo mantendrías la eficiencia ganada si todas las decisiones estratégicas dependieran de revisiones prolongadas?'};
const CRITERIA=['Eficiencia','Interpretabilidad','Ética','Impacto organizacional','Responsabilidad'];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const empty=()=>({chapter:0,phase:'intro',responses:[],matrix:{},condition:'',verdict:'',peer:'',reflection:''});
let state;try{state={...empty(),...JSON.parse(localStorage.getItem(STORAGE)||'{}')}}catch{state=empty()}
if(!Array.isArray(state.responses)||!Number.isInteger(state.chapter)||state.chapter<0||state.chapter>5)state=empty();
const save=()=>localStorage.setItem(STORAGE,JSON.stringify(state));
const set=(chapter,phase)=>{state.chapter=chapter;state.phase=phase;save();render();window.scrollTo({top:0,behavior:'instant'})};
const stages=['intro','story','evidence','decision','feedback'];
function frame(title,lead,body){$('stage').innerHTML=`<div class="narrative"><div class="narrative-header"><span class="eyebrow">${state.chapter===5?'ENTREGABLE EJECUTIVO':`CAPÍTULO ${state.chapter+1} DE 5`}</span><span class="story-progress">${state.chapter===5?'CIERRE':({story:'SITUACIÓN',evidence:'EVIDENCIA',decision:'DECISIÓN',feedback:'CONSECUENCIA'}[state.phase]||'INICIO')}</span></div><h1>${title}</h1><p class="narrative-lead">${lead}</p>${body}</div>`;}
function primary(text,action,disabled=false){return `<div class="primary-area"><button class="btn narrative-primary" id="next-action" data-narrative="${action}" ${disabled?'disabled':''}>${text}</button></div>`}
function render(){let index=state.chapter,done=state.responses.length;document.querySelectorAll('#navigation').forEach(nav=>nav.innerHTML=CHAPTERS.map((c,i)=>`<div class="navitem ${i===index?'current':''} ${i<done?'visited':''}"><span>${i<done?'✓':i+1}</span>${esc(c.title)}</div>`).join('')+`<div class="navitem ${index===5?'current':''}"><span>◆</span>Veredicto ejecutivo</div>`);$('progress-bar').style.width=`${done/5*100}%`;$('progress-label').textContent=`${done} de 5 decisiones registradas`;$('stage-code').textContent='NOVADATA · CASO EN DESARROLLO';$('stage-progress').textContent=index===5?'VEREDICTO':`RONDA ${index+1} / 5`;
if(index===5){renderFinal();return;}if(state.phase==='intro'){frame('NovaData: una decisión bajo incertidumbre','Forma parte de la junta ejecutiva. El problema evolucionará conforme llegue nueva evidencia.',`<section class="story-card"><span class="eyebrow">EL DESAFÍO</span><p>La IA recomienda frenar inversiones. Los directivos tienen que decidir cuánto poder conceder al algoritmo y cómo responder por sus consecuencias.</p><div class="key-facts"><div><strong>−30 %</strong><small>tiempo de reportes</small></div><div><strong>A · B · C</strong><small>alternativas posibles</small></div><div><strong>5</strong><small>momentos de decisión</small></div></div><p class="note">Trabajarás de forma individual. Después de cada decisión podrás compartir una postura breve en Zoom. No necesitas Gemini.</p></section>${primary('Conocer la situación inicial','start')}`);return;}
const ch=CHAPTERS[index];if(state.phase==='story'){let prior=index?`<div class="previous"><strong>Tu postura anterior: ${esc(state.responses[index-1]?.choice||'—')} · ${esc(OPTIONS[state.responses[index-1]?.choice])}</strong><p>La nueva información puede confirmar o cuestionar tu criterio.</p></div>`:'';frame(ch.title,ch.subtitle,`<section class="story-card"><span class="eyebrow">QUÉ ESTÁ OCURRIENDO</span><p>${esc(ch.story)}</p>${prior}<p class="scenario-question">Tu responsabilidad: ${esc(ch.task)}</p></section>${primary('Examinar evidencia','evidence')}`);return;}
if(state.phase==='evidence'){frame('Examina lo que sabe la junta',ch.subtitle,`<section class="story-card"><span class="eyebrow">EVIDENCIA DISPONIBLE EN ESTA RONDA</span><div class="narrative-evidence">${ch.evidence.map(([label,detail],i)=>`<div class="evidence"><span class="evidence-index">${i+1}</span><div><h3>${esc(label)}</h3><p>${esc(detail)}</p></div></div>`).join('')}</div><div class="notice">Esta evidencia puede apoyar o cuestionar tu postura; aún debes interpretarla.</div></section>${primary('Tomar mi decisión','decision')}`);return;}
if(state.phase==='decision'){frame('Decide y justifica',ch.task,`<section class="story-card"><span class="eyebrow">DECISIÓN INDIVIDUAL</span><div class="options">${Object.entries(OPTIONS).map(([code,label])=>`<label class="option"><input type="radio" name="vote" value="${code}"><span class="letter">${code}</span>${esc(label)}</label>`).join('')}</div><label for="reason" class="label">Tu argumento sustentado en la evidencia (mínimo 70 caracteres)</label><textarea id="reason" rows="5" maxlength="1500" placeholder="Recomiendo esta alternativa porque... La evidencia concreta que utilizo es..."></textarea>${index===2?`<label for="risk" class="label">Riesgo prioritario</label><select id="risk"><option value="">Selecciona uno</option>${['Financiero','Estratégico','Organizacional','Ético','Reputacional'].map(x=>`<option>${x}</option>`).join('')}</select>`:''}${index===3?'<label for="safeguards" class="label">Dos salvaguardas verificables (separa con punto y coma)</label><textarea id="safeguards" rows="3" placeholder="Ej.: revisión independiente; aprobación humana para decisiones críticas"></textarea>':''}${index===4?'<label for="condition" class="label">Condición de supervisión (mínimo 35 caracteres)</label><textarea id="condition" rows="3" placeholder="La autonomía solo podría aumentar si..."></textarea>':''}<p id="validation-hint" class="micro" aria-live="polite">Selecciona una alternativa y redacta tu argumento.</p></section>${primary('Confirmar mi decisión','confirm',true)}`);bindForm(index);return;}
if(state.phase==='feedback'){const response=state.responses[index],prev=index?state.responses[index-1]?.choice:null,change=prev&&prev!==response.choice;frame('Tu decisión ya forma parte del caso',`Elegiste ${response.choice}: ${OPTIONS[response.choice]}.`, `<section class="story-card"><span class="eyebrow">RETROALIMENTACIÓN INMEDIATA</span><div class="selected-decision">${esc(response.choice)} · ${esc(OPTIONS[response.choice])}</div><p>${change?'Modificaste tu postura frente a la ronda anterior.':'Mantuviste una posición. Si hay nuevas objeciones, tendrás que defenderla con evidencia.'}</p><div class="challenge"><strong>Una voz del comité te cuestiona:</strong><p>${esc(CRITIQUE[response.choice])}</p></div><div class="zoom-box"><span class="eyebrow">SOCIALIZACIÓN EN ZOOM</span><p>${esc(ch.zoom)}</p><div class="zoom-message" id="zoom-message">R${index+1} · ${esc(response.choice)} · ${esc(response.argument.slice(0,105))}</div><button class="btn secondary" id="copy-zoom">Copiar para el chat</button><span class="micro" id="zoom-status">Opcional: pégalo en el chat de Zoom.</span></div></section>${primary(index===4?'Elaborar veredicto ejecutivo':'Descubrir qué sucede después','advance')}`);$('copy-zoom').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('zoom-message').textContent);$('zoom-status').textContent='Mensaje copiado. Pégalo en Zoom.'}catch{$('zoom-status').textContent='Selecciona el mensaje y cópialo manualmente.'}});}}
function bindForm(index){const validate=()=>{const code=document.querySelector('[name=vote]:checked')?.value,reason=$('reason').value.trim();let valid=!!code&&reason.length>=70;let hint=`${reason.length}/70 caracteres.`;if(index===2){valid&&=!!$('risk').value;hint+=' Selecciona un riesgo prioritario.'}if(index===3){valid&&=$('safeguards').value.split(';').filter(x=>x.trim().length>=12).length>=2;hint+=' Indica dos salvaguardas separadas con punto y coma.'}if(index===4){valid&&=$('condition').value.trim().length>=35;hint+=' Indica una condición verificable.'}$('next-action').disabled=!valid;$('validation-hint').textContent=hint;};document.querySelectorAll('.narrative input,.narrative textarea,.narrative select').forEach(x=>x.addEventListener('input',validate));validate();}
function confirmDecision(){const i=state.chapter,code=document.querySelector('[name=vote]:checked')?.value,reason=$('reason')?.value.trim();if(!code||reason.length<70||state.responses.length!==i)return;const response={choice:code,argument:reason};if(i===2)response.risk=$('risk').value;if(i===3)response.safeguards=$('safeguards').value.trim();if(i===4)response.condition=$('condition').value.trim();state.responses.push(response);set(i,'feedback');}
function renderFinal(){frame('Tu veredicto ante la junta','Conecta tus cinco decisiones con una matriz profesional y el argumento que escuchaste en Zoom.',`<section class="story-card"><span class="eyebrow">EVOLUCIÓN DE TU CRITERIO</span><div class="timeline">${state.responses.map((r,i)=>`<div class="timeline-item"><span class="timeline-badge">${esc(r.choice)}</span><div><strong>${esc(CHAPTERS[i].title)}</strong><p>${esc(OPTIONS[r.choice])}</p></div></div>`).join('')}</div></section><section class="story-card"><span class="eyebrow">MATRIZ DE DECISIÓN</span><p>Para cada criterio, escribe una evidencia, un riesgo y una implicación.</p><div class="table-scroll"><table><thead><tr><th>Criterio</th><th>Evidencia</th><th>Riesgo</th><th>Implicación</th></tr></thead><tbody>${CRITERIA.map((criterion,i)=>`<tr><th>${criterion}</th>${['evidence','risk','impact'].map(k=>`<td><textarea rows="3" data-matrix="${i}:${k}" aria-label="${k} de ${criterion}" placeholder="Escribe una idea concreta"></textarea></td>`).join('')}</tr>`).join('')}</tbody></table></div><label class="label" for="final-condition">Condición de supervisión</label><textarea id="final-condition" rows="3"></textarea><label class="label" for="verdict">Veredicto ejecutivo de 30–45 segundos</label><textarea id="verdict" rows="5" placeholder="Recomiendo... porque... El principal riesgo... y establecería..."></textarea></section><section class="story-card"><span class="eyebrow">CONTRASTE COLECTIVO EN ZOOM</span><label class="label" for="peer">¿Qué argumento distinto escuchaste?</label><textarea id="peer" rows="3" placeholder="Una postura diferente señaló que..."></textarea><label class="label" for="reflection">¿Cómo modificó, fortaleció o complicó tu postura?</label><textarea id="reflection" rows="3" placeholder="Mi criterio cambió o se fortaleció porque..."></textarea><p class="note">Si no participaste en el debate, puedes señalarlo con honestidad. No hay verificación automática de Zoom.</p></section><section class="story-card"><span class="eyebrow">CONTRASTE CON GEMINI · OPCIONAL</span><p>El caso ya puede completarse sin Gemini. Si deseas ampliar el debate, copia un prompt de cuestionamiento crítico.</p><button class="btn secondary" id="gemini-prompt">Copiar prompt para Gemini</button><p class="micro" id="gemini-status"></p></section><div id="final-error" class="error hidden" role="alert"></div>${primary('Generar y descargar mi ficha','download')}`);document.querySelectorAll('[data-matrix]').forEach(x=>x.value=state.matrix[x.dataset.matrix]||'');for(const [id,key] of [['final-condition','condition'],['verdict','verdict'],['peer','peer'],['reflection','reflection']])$(id).value=state[key]|| (key==='condition'?state.responses[4]?.condition||'':'');$('gemini-prompt').addEventListener('click',copyGemini);}
function report(){return `NOVADATA CONSULTING · OPEN CLASS 4\nVEREDICTO EJECUTIVO\n==============================\n\nRECORRIDO INDIVIDUAL\n${state.responses.map((r,i)=>`Ronda ${i+1} — ${CHAPTERS[i].title}\nDecisión: ${r.choice} / ${OPTIONS[r.choice]}\nArgumento: ${r.argument}${r.risk?'\nRiesgo: '+r.risk:''}${r.safeguards?'\nSalvaguardas: '+r.safeguards:''}`).join('\n\n')}\n\nMATRIZ EJECUTIVA\n${CRITERIA.map((c,i)=>`${c}\nEvidencia: ${state.matrix[i+':evidence']}\nRiesgo: ${state.matrix[i+':risk']}\nImplicación: ${state.matrix[i+':impact']}`).join('\n\n')}\n\nCONDICIÓN DE SUPERVISIÓN\n${state.condition}\n\nVEREDICTO\n${state.verdict}\n\nDISCUSIÓN EN ZOOM\nArgumento escuchado: ${state.peer||'No registrado'}\nReflexión: ${state.reflection||'No registrada'}\n\nMaterial didáctico. La autorización de decisiones críticas requiere juicio y responsabilidad humana.`;}
function downloadReport(){const matrix={};document.querySelectorAll('[data-matrix]').forEach(x=>matrix[x.dataset.matrix]=x.value.trim());const missing=Object.values(matrix).filter(x=>x.length<12).length,condition=$('final-condition').value.trim(),verdict=$('verdict').value.trim();if(missing||condition.length<35||verdict.length<100){$('final-error').classList.remove('hidden');$('final-error').textContent=`Completa las 15 celdas de la matriz (faltan ${missing}), una condición de al menos 35 caracteres y un veredicto de al menos 100.`;return;}Object.assign(state,{matrix,condition,verdict,peer:$('peer').value.trim(),reflection:$('reflection').value.trim()});save();$('final-error').classList.add('hidden');const blob=new Blob(['\ufeff'+report()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='NovaData_OpenClass4_Veredicto_V3.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);$('next-action').textContent='Descargar mi ficha nuevamente';}
async function copyGemini(){const c=state.responses[4]?.choice;const prompt=`Actúa como integrante crítico de la junta de NovaData Consulting. Mi decisión final es ${c}: ${OPTIONS[c]}. Mi razonamiento: ${state.responses[4]?.argument}. Interrógame con preguntas socráticas, de una en una, sobre interpretabilidad, eficiencia, impactos éticos y gobernanza. No inventes datos del caso ni decidas por mí.`;try{await navigator.clipboard.writeText(prompt);$('gemini-status').textContent='Prompt copiado. Su uso es opcional.'}catch{$('gemini-status').textContent='No se pudo copiar automáticamente. Selecciona este texto:';const x=document.createElement('textarea');x.value=prompt;x.readOnly=true;$('gemini-status').after(x)}}
document.addEventListener('click',e=>{const action=e.target.closest('[data-narrative]')?.dataset.narrative;if(!action)return;if(action==='start')set(0,'story');if(action==='evidence')set(state.chapter,'evidence');if(action==='decision')set(state.chapter,'decision');if(action==='confirm')confirmDecision();if(action==='advance')set(state.chapter+1,state.chapter===4?'final':'story');if(action==='download')downloadReport();});$('reset').addEventListener('click',()=>{if(confirm('¿Reiniciar todo el caso? Se perderán las respuestas guardadas en este navegador.')){localStorage.removeItem(STORAGE);state=empty();render();window.scrollTo({top:0,behavior:'instant'});}});render();
